<?php $pageTitle='Manage Doctors'; include __DIR__.'/../includes/header.php'; require_login('administrator'); $rows=Database::connection()->query('SELECT d.*, u.name doctor_name, dep.name department FROM doctors d JOIN users u ON u.id=d.user_id JOIN departments dep ON dep.id=d.department_id')->fetchAll(); ?>
<h1>Manage Doctors</h1><table class="table"><tr><th>Name</th><th>Department</th><th>Specialization</th><th>Fee</th><th>Availability</th></tr><?php foreach($rows as $r): ?><tr><td><?= e($r['doctor_name']) ?></td><td><?= e($r['department']) ?></td><td><?= e($r['specialization']) ?></td><td><?= e($r['consultation_fee']) ?></td><td><?= e($r['availability']) ?></td></tr><?php endforeach; ?></table><?php include __DIR__.'/../includes/footer.php'; ?>
